  street: null,
  barangay: null,
  city: null,
  landmarks: null,
  notes: null,
  fullAddress: null,
  isDeliverable: false
};

return {
  json: {
    userId: psid,
    items: items,
    itemCount: itemCount,
    createdAt: createdAt,
    updatedAt: formattedDate,
